style.css:
/* Fondo pastel estilo cute */
body {
  margin: 0;
  height: 100vh;
  background: 
    radial-gradient(circle at 10% 20%, rgba(255, 156, 207, 0.3), transparent 25%),
    radial-gradient(circle at 90% 80%, rgba(168, 216, 255, 0.25), transparent 20%),
    radial-gradient(circle at 50% 50%, rgba(255, 217, 166, 0.3), transparent 30%),
    #fff8fb; /* color base */
  background-repeat: no-repeat;
  background-size: cover;
}
